{
  "checks": [
    {
      "problem": "链路明细里每个产品只展示开头几步的截图,后面的步骤没有图,读者无法在页面上核对问题清单和结论提到的那些界面",
      "A": "部分解决",
      "B": "解决"
    },
    {
      "problem": "问题清单、改进建议和链路明细之间没有互相引用的定位信息(问题编号、步骤号、屏名),读者要在几节之间来回数步骤、对编号",
      "A": "部分解决",
      "B": "解决"
    }
  ],
  "worse": [
    {
      "version": "A",
      "where": "链路明细 · 快送 11.2",
      "why": "快送只给了第 1–4 步的截图,第 5 步「支付成功」没有图,而结论里专门提到两款 App 的链路长度(快送 5 屏),读者在页面上找不到快送最后一屏可核对;相比之下 B 版把快送第 5 步的支付成功屏也放出来了。同时 A 版把 4 张图压在一行里,截屏里的「再买 X 元减 Y 元」「默认选第一张」等小字更难看清,看图对应文字时更费劲。"
    }
  ],
  "better": "B",
  "reason": "B 版把两款产品的每一步(含快送第 5 步支付成功)都配了截图,并在链路明细的步骤标题上直接标了 P1/P2/P3,读者不用回到问题清单数步骤就能把图、步骤、问题对上;A 版既缺快送最后一屏的图,步骤标题里也没有问题编号。",
  "next": [
    {
      "where": "问题清单 → 链路明细",
      "task": "从某个问题(如 P1 默认不选最优券)直接找到对应界面核对",
      "why": "问题表只写「快送 / 第 3 步」,没有屏名或可点击的定位,读者仍要跳到链路明细里按产品名+步骤号去找那一屏。"
    },
    {
      "where": "下一步 · 改进建议的「依据」",
      "task": "看某条建议是依据哪个界面提出的",
      "why": "依据只写「小橙第 2 步、P1」,而 P1 对应的是快送第 3 步选券屏,读者要回到链路明细才知道 P1 是哪一屏,建议与问题、界面之间还差一步对照。"
    }
  ]
}
